// console.log("================ FINISHED DEBUG ================");

(function execute(inputs, outputs) {
    var stagingSysId = inputs.staging_sys_id;
    var userPassword = inputs.password; 

    gs.info("[Password Submit Debug] Starting user creation for staging ID: " + stagingSysId);

    if (!stagingSysId || !userPassword) {
        gs.error("[Password Submit Debug] FAILED: Missing staging_sys_id or password input.");
        return;
    }

    var stagingGr = new GlideRecord('x_travel_buddy_app_user_password_registration');

    if (stagingGr.get(stagingSysId)) {

        if (stagingGr.u_status == 'completed' || stagingGr.u_token_used == true) {
            gs.warn("[Password Submit Debug] FAILED: Staging record is already completed or token was used.");
            return;
        }

        var username = stagingGr.u_username || stagingGr.u_email;

       
        var userGr = new GlideRecord('sys_user');
        userGr.initialize();
        userGr.first_name = stagingGr.u_first_name;
        userGr.last_name = stagingGr.u_last_name;
        userGr.email = stagingGr.u_email;
        userGr.user_name = username;
        userGr.user_password = userPassword; 
        userGr.active = true;

        gs.info("[Password Submit Debug] Attempting sys_user insert for username: " + username);
        var newUserId = userGr.insert();

        if (newUserId) {
            
            stagingGr.u_status = 'completed';
            stagingGr.u_token_used = true;
            stagingGr.update();

            outputs.created_user_sys_id = newUserId;
            outputs.user_email = stagingGr.u_email;

            gs.info("[Password Submit Debug] SUCCESS: User created in sys_user ID: " + newUserId + " and staging set to completed.");
        } else {
            gs.error("[Password Submit Debug] FAILED: userGr.insert() returned null. Check sys_user mandatory fields/data policies.");
        }
    } else {
        gs.error("[Password Submit Debug] FAILED: Staging record not found for sys_id: " + stagingSysId);
    }
})(inputs, outputs);

